//-----------------------------------------------------------
// Description: This testbench streams complete TUs, changes
// all stimulus signals only on positive clock edges, and
// checks four coefficients and TU metadata at every output
// handshake. Source and expected beats are generated by
// ref/generate_vectors.py from the VTM integer formula.
//-----------------------------------------------------------
`timescale 1ns/1ps
module TQ_QUANTIZATION_ENGINE_TB;
  localparam PARA_NUM_BEATS = 388;
  logic                I_CLK;
  logic                I_RESETN;
  logic [63:0]         I_DATA;
  logic                I_DATA_VALID;
  logic                I_DATA_READY;
  logic                I_DATA_LAST;
  logic                I_TU_START;
  logic                I_TU_LAST;
  logic [1:0]          I_TU_WIDTH_SIZE;
  logic [1:0]          I_TU_HEIGHT_SIZE;
  logic [1:0]          I_ROW_TRANSFORM_MODE;
  logic [1:0]          I_COLUMN_TRANSFORM_MODE;
  logic [15:0]         I_TU_ID;
  logic [6:0]          I_QP_PRIME;
  logic                I_IS_IRAP;
  logic [63:0]         O_DATA;
  logic                O_DATA_VALID;
  logic                O_DATA_READY;
  logic                O_DATA_LAST;
  logic                O_TU_START;
  logic                O_TU_LAST;
  logic [1:0]          O_TU_WIDTH_SIZE;
  logic [1:0]          O_TU_HEIGHT_SIZE;
  logic [1:0]          O_ROW_TRANSFORM_MODE;
  logic [1:0]          O_COLUMN_TRANSFORM_MODE;
  logic [15:0]         O_TU_ID;
  logic [6:0]          O_QP_PRIME;
  logic                O_IS_IRAP;
  logic [3:0]          O_CLIPPED;
  logic [63:0]         r_input_mem [0:PARA_NUM_BEATS-1];
  logic [63:0]         r_golden_mem [0:PARA_NUM_BEATS-1];
  logic [63:0]         r_meta_mem [0:PARA_NUM_BEATS-1];
  logic [3:0]          r_clipped_mem [0:PARA_NUM_BEATS-1];
  logic [3:0]          r_prev_clipped;
  logic [63:0]         r_prev_data;
  logic [34:0]         r_prev_meta;
  integer              r_cycle;
  integer              r_received;
  integer              r_errors;
  logic                r_prev_stalled;
  logic [34:0]         w_actual_meta;

  TQ_QUANTIZATION_ENGINE u_dut (
    .I_CLK                    (I_CLK),
    .I_RESETN                 (I_RESETN),
    .I_DATA                   (I_DATA),
    .I_DATA_VALID             (I_DATA_VALID),
    .I_DATA_READY             (I_DATA_READY),
    .I_DATA_LAST              (I_DATA_LAST),
    .I_TU_START               (I_TU_START),
    .I_TU_LAST                (I_TU_LAST),
    .I_TU_WIDTH_SIZE          (I_TU_WIDTH_SIZE),
    .I_TU_HEIGHT_SIZE         (I_TU_HEIGHT_SIZE),
    .I_ROW_TRANSFORM_MODE     (I_ROW_TRANSFORM_MODE),
    .I_COLUMN_TRANSFORM_MODE  (I_COLUMN_TRANSFORM_MODE),
    .I_TU_ID                  (I_TU_ID),
    .I_QP_PRIME               (I_QP_PRIME),
    .I_IS_IRAP                (I_IS_IRAP),
    .O_DATA                   (O_DATA),
    .O_DATA_VALID             (O_DATA_VALID),
    .O_DATA_READY             (O_DATA_READY),
    .O_DATA_LAST              (O_DATA_LAST),
    .O_TU_START               (O_TU_START),
    .O_TU_LAST                (O_TU_LAST),
    .O_TU_WIDTH_SIZE          (O_TU_WIDTH_SIZE),
    .O_TU_HEIGHT_SIZE         (O_TU_HEIGHT_SIZE),
    .O_ROW_TRANSFORM_MODE     (O_ROW_TRANSFORM_MODE),
    .O_COLUMN_TRANSFORM_MODE  (O_COLUMN_TRANSFORM_MODE),
    .O_TU_ID                  (O_TU_ID),
    .O_QP_PRIME               (O_QP_PRIME),
    .O_IS_IRAP                (O_IS_IRAP),
    .O_CLIPPED                (O_CLIPPED)
  );

  always #5 I_CLK = ~I_CLK;
  assign w_actual_meta = {O_COLUMN_TRANSFORM_MODE, O_ROW_TRANSFORM_MODE, O_TU_ID, O_QP_PRIME, O_IS_IRAP, O_TU_HEIGHT_SIZE, O_TU_WIDTH_SIZE, O_TU_LAST, O_TU_START, O_DATA_LAST};

  // The producer drives only after posedge using nonblocking assignments.
  initial begin
    I_CLK = 1'b0;
    I_RESETN = 1'b0;
    I_DATA = '0;
    I_DATA_VALID = 1'b0;
    I_DATA_LAST = 1'b0;
    I_TU_START = 1'b0;
    I_TU_LAST = 1'b0;
    I_TU_WIDTH_SIZE = 2'b00;
    I_TU_HEIGHT_SIZE = 2'b00;
    I_ROW_TRANSFORM_MODE = 2'b00;
    I_COLUMN_TRANSFORM_MODE = 2'b00;
    I_TU_ID = '0;
    I_QP_PRIME = 7'd0;
    I_IS_IRAP = 1'b0;
    O_DATA_READY = 1'b0;
    $readmemh("tb/quant_input.mem", r_input_mem);
    $readmemh("tb/quant_expected.mem", r_golden_mem);
    $readmemh("tb/quant_metadata.mem", r_meta_mem);
    $readmemh("tb/quant_clipped.mem", r_clipped_mem);
    repeat (5) @(posedge I_CLK);
    I_RESETN <= 1'b1;
    @(posedge I_CLK);
    for (integer b = 0; b < PARA_NUM_BEATS; b = b + 1) begin
      I_DATA <= r_input_mem[b];
      I_DATA_VALID <= 1'b1;
      I_DATA_LAST <= r_meta_mem[b][0];
      I_TU_START <= r_meta_mem[b][1];
      I_TU_LAST <= r_meta_mem[b][2];
      I_TU_WIDTH_SIZE <= r_meta_mem[b][4:3];
      I_TU_HEIGHT_SIZE <= r_meta_mem[b][6:5];
      I_IS_IRAP <= r_meta_mem[b][7];
      I_QP_PRIME <= r_meta_mem[b][14:8];
      I_TU_ID <= r_meta_mem[b][30:15];
      I_ROW_TRANSFORM_MODE <= r_meta_mem[b][32:31];
      I_COLUMN_TRANSFORM_MODE <= r_meta_mem[b][34:33];
      @(posedge I_CLK);
      while (!I_DATA_READY)
        @(posedge I_CLK);
    end
    I_DATA_VALID <= 1'b0;
    while (r_received < PARA_NUM_BEATS)
      @(posedge I_CLK);
    repeat (2) @(posedge I_CLK);
    if (r_errors == 0)
      $display("PASS: Quantization %0d beats (six TUs), metadata, and backpressure", PARA_NUM_BEATS);
    else
      $display("FAIL: Quantization errors=%0d", r_errors);
    $finish;
  end

  // Ready is also driven only at positive clock edges.
  always @(posedge I_CLK) begin
    if (!I_RESETN) begin
      O_DATA_READY <= 1'b0;
      r_cycle <= 0;
    end
    else begin
      O_DATA_READY <= (r_cycle % 13 >= 4);
      r_cycle <= r_cycle + 1;
    end
  end

  always @(posedge I_CLK) begin
    if (!I_RESETN) begin
      r_received = 0;
      r_errors = 0;
      r_prev_stalled = 1'b0;
    end
    else begin
      if (r_prev_stalled) begin
        if (!O_DATA_VALID || O_DATA !== r_prev_data || w_actual_meta !== r_prev_meta || O_CLIPPED !== r_prev_clipped) begin
          $display("ERROR: data or metadata changed during output stall");
          r_errors = r_errors + 1;
        end
      end
      r_prev_stalled = O_DATA_VALID && !O_DATA_READY;
      if (r_prev_stalled) begin
        r_prev_data = O_DATA;
        r_prev_meta = w_actual_meta;
        r_prev_clipped = O_CLIPPED;
      end
      if (O_DATA_VALID && O_DATA_READY) begin
        if (r_received >= PARA_NUM_BEATS) begin
          r_errors = r_errors + 1;
          $display("ERROR: extra output beat");
        end
        else begin
          if (O_DATA !== r_golden_mem[r_received]) begin
            $display("ERROR: beat=%0d expected=%h received=%h", r_received, r_golden_mem[r_received], O_DATA);
            for (integer lane = 0; lane < 4; lane = lane + 1)
              $display("  lane=%0d expected=%0d actual=%0d", lane, $signed(r_golden_mem[r_received][lane*16 +:16]), $signed(O_DATA[lane*16 +:16]));
            r_errors = r_errors + 1;
          end
          if (O_CLIPPED !== r_clipped_mem[r_received]) begin
            $display("ERROR: clip flags beat=%0d expected=%b actual=%b", r_received, r_clipped_mem[r_received], O_CLIPPED);
            r_errors = r_errors + 1;
          end
          if (w_actual_meta !== r_meta_mem[r_received][34:0]) begin
            $display("ERROR: metadata beat=%0d expected=%h actual=%h", r_received, r_meta_mem[r_received][34:0], w_actual_meta);
            r_errors = r_errors + 1;
          end
          if (O_TU_START || O_TU_LAST)
            $display("TU=%0d beat=%0d START=%b LAST=%b DATA=%h", O_TU_ID, r_received, O_TU_START, O_TU_LAST, O_DATA);
        end
        r_received = r_received + 1;
      end
    end
  end

  initial begin
    repeat (20000) @(posedge I_CLK);
    $fatal(1, "TIMEOUT: incomplete quantization stream");
  end
endmodule: TQ_QUANTIZATION_ENGINE_TB
